[1943] = { en = "Speak with Deino", tier = 2,
  t = "Praat met Deino",
  d = "De trollenmagiër Deino heeft je hulp nodig, $N. Ze woont in Orgrimmar, in de Darkbriar Lodge.",
  o = "Praat met Deino.",
  c = "Goed, je bent gekomen. Mijn taak is niet makkelijk, maar wel heel belangrijk voor het genootschap van magiërs. Als je me helpt, weet ik zeker dat je het de moeite waard vindt.",
  g = { {"trollenmagiër", "troll mage"}, {"woont", "lives (wonen)"}, {"genootschap", "society"}, {"de moeite waard", "worthwhile"} },
},

[1944] = { en = "Waters of Xavian", tier = 2,
  t = "Het water van Xavian",
  d = "De beroemde stad Xavian ligt diep verborgen in het oosten van Ashenvale. De verhalen over haar oude kennis zijn goed bekend bij geleerden. Men zegt dat het water van Xavian grote magische krachten heeft.$B$BIk wil graag een monster van dat water, van de bron.$B$BNeem deze fles mee en ga naar Xavian. Schep water onder aan de hoogste waterval, en kom dan bij me terug. En wees voorzichtig als je door die oude stad loopt. Saters hebben de ruïnes nu in handen, en ze houden er niet van als magiërs zich met hun zaken bemoeien.",
  o = "Breng het Xavian Water Sample naar Deino in Orgrimmar.",
  p = "Ik ben blij dat je heelhuids terug bent, $N. Heb je het watermonster? Ik wil graag de eigenschappen ervan bestuderen.",
  c = "Ah, heel goed. Ik hoop dat de saters van Xavian je niet veel problemen gaven?$B$BDank je, $N. Ik ga dit monster van het water van Xavian meteen bestuderen.",
  g = { {"beroemde", "fabled, famous (beroemd)"}, {"verborgen", "hidden"}, {"kennis", "knowledge"}, {"geleerden", "scholars, the learned (geleerde)"}, {"men zegt", "it is said"}, {"monster", "sample"}, {"bron", "source, spring"}, {"schep", "scoop (scheppen)"}, {"waterval", "waterfall"}, {"saters", "satyrs (sater)"}, {"in handen", "in their hands, held"}, {"bemoeien", "meddle, pry (zich bemoeien)"}, {"heelhuids", "unharmed, in one piece"}, {"eigenschappen", "properties (eigenschap)"} },
},

[1945] = { en = "Laughing Sisters", tier = 2,
  t = "De Laughing Sisters",
  d = "Als dank voor je diensten heb ik gezorgd dat er een nieuw gewaad voor je wordt gemaakt. Maar dan moet je wel de nodige materialen verzamelen...$B$BVoor dit gewaad moet je terug naar Ashenvale. Daar haal je haarlokken van de laughing sisters. Dat zijn dryaden die zich verzamelen bij de Raynewood Retreat.$B$BAls je hun haar hebt, breng je het naar Kil'hala. Hij is een trollenkleermaker bij de Crossroads in The Barrens. Hij verwacht je, en hij zal je gewaad maken.",
  o = "Breng 12 Laughing Sister's Hairs naar Kil'hala bij de Crossroads.",
  p = "Gegroet, $N. Deino zei dat je zou komen met het haar van de laughing sisters. Heb je het?",
  c = "Ah, van dit haar kan ik een prachtig gewaad weven, $N. Het is jammer dat de laughing sisters moesten sterven om het af te staan. Maar ik betwijfel of ze het ooit vrijwillig zouden geven.$B$BHet is jammer, maar niet heel erg.",
  g = { {"diensten", "services (dienst)"}, {"gezorgd", "arranged (zorgen)"}, {"nodige", "necessary (nodig)"}, {"haarlokken", "locks of hair (haarlok)"}, {"dryaden", "dryads (dryade)"}, {"trollenkleermaker", "troll tailor"}, {"verwacht", "expects (verwachten)"}, {"weven", "weave"}, {"jammer", "a pity"}, {"af te staan", "to give up, part with (afstaan)"}, {"betwijfel", "doubt (betwijfelen)"}, {"vrijwillig", "willingly"} },
},

